          options: ["Low-dose antipsychotic medication", "Physical restraints to prevent injury", "Nonpharmacological interventions including environmental modification, music therapy, and structured activities", "Benzodiazepine administration for immediate calming"].map((text, i) => ({text, isCorrect: i === 2})),
