async function seedFadingVoices() {
  try {
    await mongoose.connect(process.env.MONGODB_URI);
    console.log('✅ Connected to MongoDB');

    const existing = await Course.findOne({ slug: FADING_VOICES_COURSE.slug });
    if (existing) {
      console.log('⚠️  Course already exists, updating...');
      await Course.findOneAndUpdate({ slug: FADING_VOICES_COURSE.slug }, FADING_VOICES_COURSE, { new: true });
      console.log('✅ Course updated successfully');
    } else {
      const course = await Course.create(FADING_VOICES_COURSE);
      console.log(`✅ Course created: "${course.title}"`);
    }

    // Stats
    const modules = FADING_VOICES_COURSE.modules;
    const totalKC = modules.reduce((sum, m) => sum + m.contentBlocks.filter(b => b.type === 'multipleChoice').length, 0);
    console.log('\n📊 Course Statistics:');
    console.log(`   Title: ${FADING_VOICES_COURSE.title}`);
    console.log(`   CE Hours: ${FADING_VOICES_COURSE.ceuHours}`);
    console.log(`   Modules: ${modules.length}`);
    console.log(`   In-Module Knowledge Checks: ${totalKC}`);
    console.log(`   Final Exam Questions: ${FADING_VOICES_COURSE.assessment.questions.length}`);
    console.log(`   Word Count: ${FADING_VOICES_COURSE.wordCount.toLocaleString()}`);
    console.log(`   Words/CE Hour: ${Math.round(FADING_VOICES_COURSE.wordCount / FADING_VOICES_COURSE.ceuHours).toLocaleString()}`);
    console.log(`   Objectives: ${FADING_VOICES_COURSE.objectives.length}`);
    console.log(`   References: ${FADING_VOICES_COURSE.references.length}`);
    console.log(`   Pass Threshold: ${FADING_VOICES_COURSE.assessment.passThreshold * 100}%`);

  } catch (error) {
    console.error('❌ Error:', error.message);
    console.error(error.stack);
  } finally {
    await mongoose.disconnect();
  }
}

seedFadingVoices();
